export const DEMO_STAGES=[
 {role:'LiteratureReader',name:'梳理论文主张',duration:2200,detail:'展示论文实验目标、指标与原文出处的整理过程。',events:['读取已导入的论文信息','展示实验主张整理步骤']},
 {role:'CodeInspector',name:'对照代码材料',duration:2400,detail:'展示代码入口、依赖与评估脚本的核对过程。',events:['展示代码目录核对步骤','展示方法与实现对应关系']},
 {role:'Planner',name:'安排核查顺序',duration:1800,detail:'按预设脚本安排指标、数据划分与实验配置核查。',events:['生成演示检查顺序','设置演示阶段与停止条件']},
 {role:'ExperimentRunner',name:'播放实验过程',duration:4400,detail:'播放环境准备、实验运行与输出收集的演示步骤。',events:['展示环境准备步骤','展示实验运行步骤','展示输出收集步骤']},
 {role:'CrossAuditor',name:'交叉核对结果',duration:3200,detail:'按选定场景整理八项复现条件与示例问题。',events:['展示指标与数据交叉核对','整理预设问题及建议']},
 {role:'Reporter',name:'生成演示报告',duration:2000,detail:'汇总预设结论、已导入材料信息与下一步建议。',events:['汇总演示结果','准备可下载的演示报告']}
];
export const DEMO_TOTAL=DEMO_STAGES.reduce((n,s)=>n+s.duration,0);
const dimensions=[['scope','复现目标'],['code','代码与版本'],['data','数据与划分'],['environment','环境重建'],['settings','实验设置'],['workflow','执行流程'],['resources','计算与预算'],['results','结果验收']];
export const DEMO_SCENARIOS={issues:{name:'发现待修正项',summary:'建议修正关键问题后复核',description:'示例报告包含指标口径、数据划分和实验设置三项待关注问题。',states:['pass','pass','attention','unknown','attention','pass','pass','attention']},clean:{name:'条件全部符合',summary:'当前演示检查项均符合',description:'展示材料齐备、检查项均符合时的报告形态。',states:Array(8).fill('pass')},missing:{name:'材料不足待补充',summary:'补齐关键材料后再评估',description:'展示数据、环境和结果依据不足时的报告形态。',states:['pass','pass','unknown','unknown','attention','pass','unknown','unknown']}};
const findings=[
 {id:'metric',dimension:'results',title:'指标计算口径需要统一',point:'示例检查点：Macro / Micro 平均方式',detail:'预设场景中，论文报告值与评估脚本采用了不同平均方式。',suggestion:'明确指标平均方式、类别权重和缺失类别处理规则，并重新计算对照值。'},
 {id:'split',dimension:'data',title:'数据划分依据需要核对',point:'示例检查点：训练集与测试集样本标识',detail:'预设场景中，数据划分缺少可复查的样本清单。',suggestion:'补充划分脚本、随机种子与样本清单，检查划分交集。'},
 {id:'settings',dimension:'settings',title:'基线与方法的训练配置需要对齐',point:'示例检查点：训练预算和模型选择',detail:'预设场景中，方法与基线的训练预算或模型选择规则不一致。',suggestion:'对齐训练步数、停止规则和调参范围，保留配置与选择依据。'}
];
export function materialKey(p){return JSON.stringify({paper:[p.paper?.sha256||p.paper?.url||'',p.paper?.name,p.paper?.pages?.length],code:[p.repository?.sha256||p.repository?.commit||'',p.repository?.name,(p.repository?.files||[]).map(f=>f.path)]});}
export function demoBlocker(p){if(!p.paper?.pages?.length)return '先导入可读取的论文 PDF。';if(!p.repository?.files?.length)return '先导入代码 ZIP 或读取 GitHub 目录。';return '';}
export function newDemo(p,scenario='issues',now=new Date().toISOString()){const reason=demoBlocker(p);if(reason)throw Error(reason);return {format:'articheck-frontend-demo-v1',data_source:'frontend_demo',scientific_validation:false,material_key:materialKey(p),scenario:DEMO_SCENARIOS[scenario]?scenario:'issues',status:'running',elapsed_ms:0,created_at:now,finished_at:null,materials:{paper_name:p.paper.name,paper_sha256:p.paper.sha256||null,paper_pages:p.paper.pages.length,repository_name:p.repository.name,repository_sha256:p.repository.sha256||p.repository.commit||null,code_files:p.repository.files.length}};}
export function advanceDemo(r,delta){if(r.status!=='running')return r;const elapsed=Math.min(DEMO_TOTAL,r.elapsed_ms+Math.max(0,delta));return {...r,elapsed_ms:elapsed,status:elapsed===DEMO_TOTAL?'completed':'running',finished_at:elapsed===DEMO_TOTAL?new Date().toISOString():null};}
export function demoPosition(r){let start=0;return DEMO_STAGES.map(s=>{const end=start+s.duration;const phase={...s,start,end,status:r.status==='completed'||r.elapsed_ms>=end?'completed':r.elapsed_ms>=start?'active':'pending'};start=end;return phase;});}
export function demoResult(r){const scenario=DEMO_SCENARIOS[r.scenario]||DEMO_SCENARIOS.issues;const rows=dimensions.map(([id,name],i)=>({id,name,status:scenario.states[i]}));const issues=r.scenario==='issues'?findings:r.scenario==='missing'?findings.filter(f=>f.id==='settings'):[];return {scenario,rows,findings:issues,counts:Object.fromEntries(['pass','attention','unknown'].map(s=>[s,rows.filter(r=>r.status===s).length]))};}
const labels={pass:'符合 · 演示',attention:'待关注 · 演示',unknown:'证据不足 · 演示'};
export class PresentationReview{
 constructor(intake){this.i=intake;this.timer=null;this.last=Date.now();this.expanded='metric';}
 restore(){for(const p of this.i.projects)if(p.presentation_review?.status==='running')p.presentation_review.status='paused';}
 invalidate(p){if(p.presentation_review){p.presentation_review.status='stale';this.i.save(p);}}
 async start(p,scenario=p.presentation_review?.scenario||'issues'){p.presentation_review=newDemo(p,scenario);this.expanded='metric';await this.i.save(p);this.i.navigate(p.id,'demo');this.watch();}
 watch(){if(this.timer)return;this.last=Date.now();this.timer=setInterval(()=>{const now=Date.now(),delta=now-this.last;this.last=now;let changed=false;for(const p of this.i.all()){const r=p.presentation_review;if(r?.status!=='running')continue;if(r.material_key!==materialKey(p)){r.status='stale';this.i.save(p);continue;}const next=advanceDemo(r,delta);p.presentation_review=next;if(demoPosition(r).filter(s=>s.status==='completed').length!==demoPosition(next).filter(s=>s.status==='completed').length||next.status==='completed')this.i.save(p);changed=true;}if(changed&&this.i.h.page()==='project'&&this.i.step==='demo')this.i.h.render();if(!this.i.all().some(p=>p.presentation_review?.status==='running')){clearInterval(this.timer);this.timer=null;}},400);}
 render(p){const r=p.presentation_review,e=x=>this.i.esc(x),reason=demoBlocker(p),stale=r&&(r.status==='stale'||r.material_key!==materialKey(p));
 if(!r||stale)return `<section class="demo-intro"><div class="demo-notice"><strong>前端演示</strong><span>播放预设评测流程与结果，不执行论文代码。</span></div><h2>${stale?'材料已更新，请重新播放':'预览完整评测流程'}</h2><p>使用当前论文与代码材料，体验从角色协作到报告审查的完整演示。</p><button class="btn primary" data-demo="start" ${reason?'disabled':''}>开始演示评测</button>${reason?`<p class="small-note">${e(reason)}</p>`:''}</section>`;
 const phases=demoPosition(r),done=phases.filter(s=>s.status==='completed').length,current=phases.find(s=>s.status==='active')||phases.at(-1),complete=r.status==='completed',result=demoResult(r),percent=Math.floor(r.elapsed_ms/DEMO_TOTAL*100);
 return `<section class="presentation-review"><div class="demo-notice"><strong>前端演示</strong><span>预设场景生成结果，仅展示交互；未执行代码或验证论文。</span></div><div class="demo-materials"><div><span>论文</span><strong>${e(r.materials.paper_name)}</strong><small>${r.materials.paper_pages} 页</small></div><div><span>代码材料</span><strong>${e(r.materials.repository_name)}</strong><small>${r.materials.code_files} 个文件目录</small></div><div><span>评测场景</span><select aria-label="演示结果场景" data-demo-scenario ${r.status==='running'?'disabled':''}>${Object.entries(DEMO_SCENARIOS).map(([id,s])=>`<option value="${id}" ${r.scenario===id?'selected':''}>${s.name}</option>`).join('')}</select></div></div>
 ${complete?this.result(p,r,result):`<div class="demo-progress-head"><div><h2>${r.status==='paused'?'演示已暂停':current.name}</h2><p>${done} / ${phases.length} 个角色阶段已播放 · ${percent}%</p></div><div>${r.status==='paused'?'<button class="btn primary" data-demo="resume">继续演示</button>':'<button class="btn" data-demo="pause">暂停</button>'}<button class="btn text" data-demo="finish">直接查看结果</button></div></div><div class="demo-progress" role="progressbar" aria-label="演示播放进度" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div><div class="demo-running-grid"><ol class="demo-timeline">${phases.map((s,index)=>`<li class="${s.status}"><span class="demo-stage-mark">${s.status==='completed'?this.i.icon('check'):index+1}</span><div><strong>${s.name}</strong><span>${s.role}</span></div><small>${s.status==='completed'?'已播放':s.status==='active'?r.status==='paused'?'已暂停':'播放中':'等待'}</small></li>`).join('')}</ol><section class="demo-current"><div class="section-heading"><h3>当前演示步骤</h3><span>${current.role}</span></div><p>${e(current.detail)}</p><div class="demo-events">${phases.flatMap(s=>s.events.map((text,index)=>({text,at:s.start+(index+1)*s.duration/(s.events.length+1),role:s.role}))).filter(item=>item.at<=r.elapsed_ms).slice(-5).map(item=>`<div><span>${this.i.icon('check')}</span><div><strong>${item.text}</strong><small>${item.role} · 演示事件</small></div></div>`).join('')||'<p>演示已启动，正在准备第一阶段。</p>'}</div><p class="demo-local-note">文件信息来自浏览器导入；以上处理步骤由演示脚本播放。</p></section></div>`}</section>`;
 }
 result(p,r,res){const e=x=>this.i.esc(x);return `<div class="demo-result-head"><div><h2>${res.scenario.summary}</h2><p>${res.scenario.description}</p></div><div class="demo-result-actions"><button class="btn" data-demo="export">${this.i.icon('download')}导出演示报告</button><button class="btn text" data-demo="start">重新播放</button></div></div><div class="demo-counts"><div><span>已展示的检查维度</span><strong>${res.rows.length}<small> 项</small></strong></div><div><span>符合</span><strong>${res.counts.pass}<small> 项</small></strong></div><div><span>待关注</span><strong>${res.counts.attention}<small> 项</small></strong></div><div><span>证据不足</span><strong>${res.counts.unknown}<small> 项</small></strong></div></div><div class="demo-result-grid"><section class="demo-findings"><div class="section-heading"><h3>示例问题与修正建议</h3><span>${res.findings.length} 项</span></div>${res.findings.length?res.findings.map((f,index)=>`<article class="demo-finding"><button data-demo="finding" data-id="${f.id}" aria-expanded="${this.expanded===f.id}"><span>${index+1}</span><strong>${f.title}</strong>${this.i.icon(this.expanded===f.id?'down':'chevron')}</button>${this.expanded===f.id?`<div class="demo-finding-body"><p class="demo-checkpoint">${e(f.point)}</p><p>${e(f.detail)}</p><h4>建议操作</h4><p>${e(f.suggestion)}</p><button class="btn text" data-demo="materials">返回材料与主张核对 ${this.i.icon('arrow')}</button></div>`:''}</article>`).join(''):'<div class="demo-no-findings"><h4>本场景没有预设问题项</h4><p>可切换演示场景，查看发现问题或材料不足时的报告。</p></div>'}</section><section class="demo-dimensions"><div class="section-heading"><h3>八项复现条件</h3></div>${res.rows.map(row=>`<div><span>${row.name}</span><strong class="demo-status-${row.status}">${labels[row.status]}</strong></div>`).join('')}<p>这里只展示预设场景。真实验收需要实际配置、实验输出与原文依据。</p></section></div><div class="demo-next"><div><h3>下一步：回到真实材料核对</h3><p>确认论文原文与代码入口，再配置真实执行流程。</p></div><button class="btn" data-demo="materials">查看已导入材料 ${this.i.icon('arrow')}</button></div>`;}
 async action(name,el){const p=this.i.current(),r=p.presentation_review;if(name==='start')return this.start(p);if(!r)return;if(r.material_key!==materialKey(p))throw Error('材料已变化，请重新开始演示。');if(name==='pause')r.status='paused';if(name==='resume'){r.status='running';this.watch();}if(name==='finish'){p.presentation_review={...r,status:'completed',elapsed_ms:DEMO_TOTAL,finished_at:new Date().toISOString()};}if(name==='materials')return this.i.navigate(p.id,'materials');if(name==='finding')this.expanded=this.expanded===el.dataset.id?null:el.dataset.id;if(name==='export'){const result=demoResult(r);this.i.h.download('articheck-demo-report.json',JSON.stringify({...r,project_id:p.id,project_title:p.title,notice:'预设前端演示结果；未执行代码，不构成论文验证。',result:{summary:result.scenario.summary,dimensions:result.rows,findings:result.findings,counts:result.counts}},null,2));return;}await this.i.save(p);this.i.h.render();}
 bind(){document.addEventListener('click',async event=>{const el=event.target.closest('[data-demo]');if(!el)return;try{await this.action(el.dataset.demo,el);}catch(error){this.i.error=error.message;this.i.h.render();}});document.addEventListener('change',async event=>{if(!event.target.matches('[data-demo-scenario]'))return;const p=this.i.current(),r=p.presentation_review;if(!r||r.status==='running')return;r.scenario=DEMO_SCENARIOS[event.target.value]?event.target.value:'issues';this.expanded='metric';await this.i.save(p);this.i.h.render();});}
}
